func handshake(clientISN, serverISN uint32) (cSeq, cAck uint32) {
    synSeq := clientISN
    synAckSeq := serverISN
    synAckAck := synSeq + 1
    if synAckAck != clientISN+1 {
        return 0, 0
    }
    finalSeq := synAckAck
    finalAck := synAckSeq
    return finalSeq, finalAck
}

